-- ================================================================================================
-- Monte Arabí · Fase 3 (N3): puntos de interés.
--
-- GENERADO por Tools/catalogo-nacional/build-poi-sql.js desde el bloque `pointsOfInterest` de
-- Frontend/Data/parks/murcia/monte-arabi/park.json. No editar a mano: regenerar con
--   node Tools/catalogo-nacional/build-poi-sql.js --park monte-arabi
--
-- Hace falta porque Frontend/Js/data.js da PRIORIDAD a la API sobre el park.json empaquetado: en un
-- despliegue con backend, sin este SQL el espacio se seguiría sirviendo con 0 puntos de interés.
--
-- ANTES DE APLICAR, comprobar que el espacio tiene fila en `parks`. Si no la tiene, el
-- INSERT ... SELECT de abajo no encuentra nada y **carga cero filas sin dar ningún error** (le pasó
-- a Sierra Espuña el 2026-08-08):
--   SELECT id, slug, name FROM parks WHERE slug = 'monte-arabi';
--
-- Idempotente: ON DUPLICATE KEY UPDATE sobre la clave única (park_id, slug). Aplicar con:
--   docker exec -i naturdex-db-1 sh -c 'MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql --default-character-set=utf8mb4 naturadex' < Database/n3-pois-monte-arabi.sql
-- ================================================================================================

-- 11 punto(s) de interés.
INSERT INTO points_of_interest (park_id, slug, name, type, description, latitude, longitude, image_url, source, is_approx)
SELECT p.id, poi.slug, poi.name, poi.type, poi.description, poi.latitude, poi.longitude, poi.image_url, poi.source, poi.is_approx
FROM parks p
JOIN (
    SELECT 'pico-del-arabi' slug, 'Pico del Arabí' name, 'Paisajístico' type, 'La cima del macizo, a 1.065 m. El plan de gestión la describe como un punto de accesibilidad visual excepcional en el Altiplano: desde arriba se abarcan el norte de la Región de Murcia y la vecina provincia de Albacete, y hacia el sur la Sierra del Cuchillo, la Sierra de la Magdalena y, al fondo, las sierras del Carche y de Salinas. El Monte Arabí es un cabezo aislado, y de ahí que se vea tanto desde él y tanto a él.' description, 38.697261 latitude, -1.282765 longitude, NULL image_url, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103 de 06.05.2025), volumen II, §3.2.1 (la cima «alcanza los 1.065 m en el pico Arabí») y §3.2.5 «Descripción del paisaje». Coordenada del vértice de OpenStreetMap (node/948505727, natural=peak), cuya cota —1.065,20 m— coincide con la que da el plan.' source, FALSE is_approx
    UNION ALL
    SELECT 'el-arabilejo', 'El Arabilejo', 'Arqueológico', 'Cerro amesetado de 913 m en cuya cima se asienta un poblado fortificado de la Edad del Bronce, del II milenio a.C. El plan de gestión calcula una veintena de cabañas y le atribuye una economía agropecuaria; la Carta Arqueológica de la Región de Murcia lo registra con cultura predominante argárica. El plan lo señala como elemento clave específico del Monumento Natural.', 38.691748, -1.285696, NULL, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103 de 06.05.2025), volumen II, §3.2.1, §3.2.3 (Tabla 48, Carta Arqueológica de la Región de Murcia) y §3.2.8 (Tabla 58, elemento clave «Yacimiento de El Arabilejo»). Coordenada de OpenStreetMap (node/2715239118, historic=archaeological_site).', FALSE
    UNION ALL
    SELECT 'cantos-de-la-visera', 'Cantos de la Visera I y II', 'Arqueológico', 'Dos abrigos formados por el desprendimiento de los acantilados próximos, con algo más de un centenar de figuras pintadas. El primero reúne unas cuarenta de estilo naturalista —bóvidos, équidos y cápridos—; el segundo, unas setenta, con fauna naturalista junto a serpentiformes, cruciformes y reticulados esquemáticos. Están declarados Bien de Interés Cultural con categoría de monumento desde el 25 de abril de 1924, y desde 1998 forman parte del Arte Rupestre del Arco Mediterráneo declarado Patrimonio de la Humanidad por la UNESCO.', 38.699472, -1.278736, 'https://commons.wikimedia.org/wiki/Special:FilePath/CantosVisera2.jpg?width=1280', 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103 de 06.05.2025), volumen II, §3.2.3 «Patrimonio cultural» y §3.2.8 (Tabla 58). La declaración BIC (25.04.1924) y el Decreto n.º 79/1998, de 28 de diciembre, que delimita su entorno de protección (BORM n.º 6 de 09.01.1999), se citan tal y como los recoge el plan: el texto de esas dos normas NO se ha consultado de primera mano. Coordenada de OpenStreetMap (node/2715239120, wikidata Q43082327), que da un solo nodo para los dos abrigos; Wikimedia Commons (foto: Clemens Schmillen, CC BY-SA 4.0)', FALSE
    UNION ALL
    SELECT 'abrigos-del-mediodia', 'Abrigos del Mediodía', 'Arqueológico', 'Estación de arte rupestre bajo un saliente que hace de marquesina sobre una planicie; en dos de los refugios del fondo hay pinturas con grupos de figuras humanas y motivos en rojo oscuro, rojo y amarillo. El plan de gestión las clasifica como arte esquematizante lineal geométrico, anterior al levantino clásico. Tienen consideración de Bien de Interés Cultural con categoría de monumento y están incluidas en la declaración de Patrimonio de la Humanidad de 1998.', 38.694606, -1.279046, NULL, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103 de 06.05.2025), volumen II, §3.2.3 «Patrimonio cultural» y §3.2.8 (Tabla 58). La condición de BIC por el artículo 40.2 de la Ley 16/1985 del Patrimonio Histórico Español y el Decreto n.º 79/1998 que delimita su entorno se citan tal y como los recoge el plan; esas normas NO se han consultado de primera mano. Coordenada de OpenStreetMap (node/2715239117, historic=archaeological_site).', FALSE
    UNION ALL
    SELECT 'petroglifos-del-arabilejo', 'Cazoletas y petroglifos del Arabilejo', 'Arqueológico', 'Grabados rupestres al pie del Arabilejo: más de medio centenar de pequeñas cazoletas semiesféricas unidas por finos canalillos serpentiformes, excavadas en la roca. El plan de gestión los relaciona con el poblado fortificado de la cima del propio Arabilejo y advierte de que su significado exacto se desconoce. Tienen consideración de Bien de Interés Cultural con categoría de monumento.', 38.690715, -1.283891, 'https://commons.wikimedia.org/wiki/Special:FilePath/InsculturasArabilejo2.jpg?width=1280', 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103 de 06.05.2025), volumen II, §3.2.3 «Patrimonio cultural» y §3.2.8 (Tabla 58, «Grabados rupestres en el Cerro Arabilejo»). La condición de BIC se cita como la recoge el plan; la norma NO se ha consultado de primera mano. Coordenada de OpenStreetMap (node/2715239122, archaeological_site=petroglyph); Wikimedia Commons (foto: Clemens Schmillen, CC BY-SA 4.0)', FALSE
    UNION ALL
    SELECT 'sucesion-miocena-del-arabi', 'Sucesión miocena del Monte Arabí', 'Geológico', 'El macizo son dos niveles de biocalcarenitas del Mioceno con, entre ellos, un ojal de materiales jurásicos empujado hacia arriba por el Trías de Montealegre del Castillo. Entre los dos tramos calcareníticos hay además una discordancia angular. El Inventario Español de Lugares de Interés Geológico lo recoge con interés principal geomorfológico y secundario sedimentológico, paleontológico y minero-metalogenético, y le asigna valor científico alto.', 38.69721, -1.287247, NULL, 'IELIG (IGME), lugar PT082 «Sucesión miocena del Monte Arabí», consultado de primera mano el 2026-08-15 en mapas.igme.es: 259,3 ha, de las que el 99,3 % caen dentro del límite del Monumento Natural y cubren el 44,2 % de su superficie. Corresponde al MU007 del inventario regional. Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103 de 06.05.2025), volumen II, §3.2.2, lo da por «propuesto como Lugar de Interés Geológico». La coordenada es el centro del polígono del LIG, no la de un afloramiento concreto: el lugar es un área que abarca casi la mitad del espacio.', TRUE
    UNION ALL
    SELECT 'la-puerta-de-la-iglesia', 'La Puerta de la Iglesia', 'Geológico', 'Acantilado que el plan de gestión cita entre las formaciones singulares del Monumento Natural, junto a las cuevas y a la zona de erosión alveolar. Es una de las paredes de la vertiente norte, la más escarpada del macizo, y es también el tipo de cortado donde el plan sitúa la nidificación de las rapaces rupícolas del espacio.', 38.703162, -1.279829, NULL, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103 de 06.05.2025), volumen II, §3.2.2 «Geología y geomorfología» y §3.2.7 (Tabla 57, elemento clave «Formaciones geomorfológicas de tipo fluvial y eólico», apartado c). Coordenada del topónimo de OpenStreetMap (place=locality), que sitúa el paraje y no la pared: por eso va marcada como aproximada.', TRUE
    UNION ALL
    SELECT 'cueva-de-la-horadada', 'Cueva de la Horadada', 'Geológico', 'Una de las grutas del modelado kárstico del Arabí, que el plan de gestión cita por su nombre entre las formaciones singulares del espacio junto a los lapiaces y las simas. La roca del macizo, biocalcarenita, se disuelve con el agua y se descama con el viento: de ahí que en el mismo monte convivan cuevas y paredes agujereadas en nido de abeja.', 38.700857, -1.279581, NULL, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103 de 06.05.2025), volumen II, §3.2.2, §3.2.5 y §3.2.7 (Tabla 57, apartado b: «modelado kárstico con presencia de lapiaces, simas y grutas (Cueva del Tesoro, Cueva de la Horadada)»). Coordenada de OpenStreetMap (node/2715239121, natural=cave_entrance). El plan NO le atribuye registro arqueológico ni la incluye en el inventario de refugios de quirópteros, que es lo que sí deja fuera del catálogo a la Cueva del Tesoro.', FALSE
    UNION ALL
    SELECT 'loma-de-los-ibanez', 'Loma de los Ibáñez', 'Paisajístico', 'La tercera elevación del Monumento Natural, de 849 m. El plan de gestión define el espacio protegido como la suma de tres relieves: la gran estructura pétrea redondeada del Arabí, el cerro amesetado del Arabilejo y esta loma, en el extremo sur del macizo.', 38.687761, -1.281004, NULL, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103 de 06.05.2025), volumen II, §3.2.1 «Justificación y caracterización» («la Loma de los Ibáñez, cuya altitud alcanza los 849 m»). Coordenada del topónimo de OpenStreetMap (place=locality, fuente Instituto Geográfico Nacional), que es el centro del paraje y no una cota: va marcada como aproximada.', TRUE
    UNION ALL
    SELECT 'pino-singular-del-arabi', 'Pino singular del Arabí', 'Natural', 'Un ejemplar de gran tamaño de pino carrasco (Pinus halepensis), inventariado como árbol singular, en el camino que da acceso a la casa del Guarda. El pino carrasco es la especie que domina el paisaje forestal del monte, cerrado en la umbría y abierto en la solana, así que este ejemplar es la medida de lo que puede llegar a crecer aquí un árbol de esa especie.', 38.689972, -1.289659, NULL, 'Plan de gestión integral de los espacios protegidos del Altiplano de la Región de Murcia (Decreto n.º 28/2025, de 10 de abril; BORM n.º 103 de 06.05.2025), volumen II, §3.2.4.2.2 («destaca un ejemplar de gran tamaño de Pinus halepensis situado en el camino que da acceso a la casa del Guarda e inventariado como árbol singular»). Coordenada del edificio de la casa del Guarda en OpenStreetMap: el plan sitúa el árbol «en el camino que da acceso» a ella, no en ella, así que la posición es representativa y va marcada como aproximada.', TRUE
    UNION ALL
    SELECT 'pocico-de-la-buitrera', 'Pocico de la Buitrera', 'Acceso', 'Área recreativa y manantial en el extremo norte del espacio protegido, junto al camino que sube al monte. Es el punto de entrada natural por esa vertiente.', 38.707259, -1.281978, NULL, 'OpenStreetMap (node/1241882295, tourism=picnic_site, y un segundo nodo natural=spring a menos de 50 m que es el mismo sitio), consultado vía Overpass el 2026-08-15 y recortado al polígono oficial. ATENCIÓN: es el único POI del espacio que NO tiene fuente documental detrás — el plan de gestión no lo nombra—, y entra por el mismo criterio con el que entró el Mirador de Rabasa en Sierra de Salinas: una instalación de uso público que ayuda a quien camina. El hecho está pendiente de contrastar con el organismo gestor.', FALSE
) poi
WHERE p.slug = 'monte-arabi'
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    type = VALUES(type),
    description = VALUES(description),
    latitude = VALUES(latitude),
    longitude = VALUES(longitude),
    image_url = VALUES(image_url),
    source = VALUES(source),
    is_approx = VALUES(is_approx);

-- Comprobación posterior: debe devolver 11.
SELECT COUNT(*) AS pois_cargados FROM points_of_interest poi
JOIN parks p ON p.id = poi.park_id WHERE p.slug = 'monte-arabi';
